def nCr(n, r):
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1
    if r > n // 2:
        r = n - r
    numerator = 1
    for i in range(r):
        numerator = numerator * (n - i)
    denominator = 1
    for i in range(1, r + 1):
        denominator = denominator * i
    return numerator // denominator

def check_n(n):
    if n % 2 == 0 or n % 3 == 0:
        return False
    for a in range(1, n + 1):
        if n // a == 2:
            mod = n - 2*a
            if mod != 0:
                val = nCr(a - 1, n - 2*a - 1)
                if val % mod != 0:
                    return False
    return True

