def is_prime(n):
    if n < 2: return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

count = 0
for n in range(5, 200):
    if is_prime(n) and n % 2 != 0 and n % 3 != 0:
        count += 1
print(count)

